//! The project law of [`super::ProjectUnits`]: a unit is this project's by
//! its key, or by a GENERATED header naming this project however the
//! header spelled the path.

use super::*;

const KEY: &str = "0a1b2c3d";

/// A systemd unit's first line, as the render writes it.
fn header(project_file: &Path) -> String {
    format!(
        "# {} {} · beat daily · do not hand-edit · regenerated by nika arm emit systemd\n",
        emit::GENERATED_MARK,
        project_file.display()
    )
}

#[cfg(unix)]
#[test]
fn a_header_naming_the_project_through_a_symlink_is_this_projects() {
    let scratch = tempfile::tempdir().expect("scratch dir");
    let real = scratch.path().join("real");
    std::fs::create_dir_all(&real).expect("project dir");
    std::fs::write(real.join("nika.yaml"), "nika: proj\n").expect("project file");
    let link = scratch.path().join("link");
    std::os::unix::fs::symlink(&real, &link).expect("symlink");
    let canonical = std::fs::canonicalize(real.join("nika.yaml")).expect("canonical file");
    let project = ProjectUnits::new(KEY.to_owned(), canonical);

    assert_eq!(
        project.owner(&header(&link.join("nika.yaml"))),
        UnitOwner::ThisProject
    );
    assert_eq!(
        project.owner(&header(&real.join("nika.yaml"))),
        UnitOwner::ThisProject
    );
    let other = scratch.path().join("other/nika.yaml");
    assert_eq!(project.owner(&header(&other)), UnitOwner::Other(other));
    assert_eq!(project.owner("[Unit]\n"), UnitOwner::Unmarked);
}

#[test]
fn only_this_projects_key_makes_a_unit_name_its_own() {
    let project = ProjectUnits::new(KEY.to_owned(), PathBuf::from("/p/nika.yaml"));
    assert!(project.keyed("nika.arm.0a1b2c3d.daily.plist"));
    assert!(project.keyed("nika.serve.0a1b2c3d.service"));
    assert!(!project.keyed("nika.arm.daily.plist"));
    assert!(!project.keyed("nika.arm.9f8e7d6c.daily.plist"));
    assert!(!project.keyed("nika.arm.0a1b2c3dx.daily.plist"));

    // An unmarked unit is this project's only under this project's key
    // (a stripped header); under another name it is nobody's to read.
    assert!(project.holds("nika.arm.0a1b2c3d.daily.plist", "<plist/>"));
    assert!(!project.holds("nika.arm.daily.plist", "<plist/>"));
    let theirs = header(Path::new("/q/nika.yaml"));
    assert!(!project.holds("nika.arm.0a1b2c3d.daily.timer", &theirs));
    assert!(project.holds("nika.arm.daily.timer", &header(Path::new("/p/nika.yaml"))));
}

#[test]
fn a_legacy_unit_is_found_with_its_owner_and_retired_unload_first() {
    let scratch = tempfile::tempdir().expect("scratch dir");
    // A space in the directory: the printed removal quotes every path.
    let dir = scratch.path().join("user units");
    std::fs::create_dir_all(&dir).expect("unit dir");
    let file = scratch.path().join("p/nika.yaml");
    let project = ProjectUnits::new(KEY.to_owned(), file.clone());
    let timer = dir.join("nika.arm.daily.timer");
    let service = dir.join("nika.arm.daily.service");
    std::fs::write(&timer, header(&file)).expect("timer");
    std::fs::write(&service, header(&file)).expect("service");

    let labels = ["daily".to_owned(), "weekly".to_owned()];
    let found = legacy_units(&dir, &labels, Target::SystemdUser, &project);
    assert_eq!(
        found,
        [LegacyUnit {
            unit: "nika.arm.daily".to_owned(),
            paths: vec![timer.clone(), service.clone()],
            owner: UnitOwner::ThisProject,
        }],
        "only the beat with an old unit"
    );
    let Some(legacy) = found.first() else {
        return;
    };
    let commands = retire_commands(legacy, Target::SystemdUser).expect("systemd retires");
    assert_eq!(
        commands,
        [
            "systemctl --user disable --now nika.arm.daily.timer".to_owned(),
            format!("rm '{}' '{}'", timer.display(), service.display()),
        ]
    );
    let commands = retire_commands(legacy, Target::Launchd).expect("launchd retires");
    assert_eq!(
        commands.first().map(String::as_str),
        Some("launchctl bootout gui/$UID/nika.arm.daily")
    );
}

/// A unit of this project whose beat the registry no longer arms is an
/// orphan: found under its keyed name with every file, with its owner; a
/// unit still armed, another project's key and the serve unit are not.
#[test]
fn an_orphan_is_a_keyed_unit_whose_beat_is_no_longer_armed() {
    let scratch = tempfile::tempdir().expect("scratch dir");
    let dir = scratch.path();
    let file = dir.join("p/nika.yaml");
    let project = ProjectUnits::new(KEY.to_owned(), file.clone());
    let ours = header(&file);
    for name in [
        "nika.arm.0a1b2c3d.gone.timer",
        "nika.arm.0a1b2c3d.gone.service",
        "nika.arm.0a1b2c3d.daily.timer",
        "nika.arm.0a1b2c3d.daily.service",
        "nika.serve.0a1b2c3d.service",
    ] {
        std::fs::write(dir.join(name), &ours).expect("unit");
    }
    std::fs::write(
        dir.join("nika.arm.9f8e7d6c.gone.timer"),
        header(Path::new("/q/nika.yaml")),
    )
    .expect("another project's unit");

    let orphans = orphan_units(dir, &["daily".to_owned()], Target::SystemdUser, &project);

    assert_eq!(orphans.len(), 1, "{orphans:?}");
    let orphan = &orphans[0];
    assert_eq!(orphan.unit, "nika.arm.0a1b2c3d.gone");
    assert_eq!(orphan.label, "gone");
    assert_eq!(
        orphan.paths,
        [
            dir.join("nika.arm.0a1b2c3d.gone.service"),
            dir.join("nika.arm.0a1b2c3d.gone.timer"),
        ]
    );
    assert_eq!(orphan.owner, UnitOwner::ThisProject);
    assert_eq!(
        orphan_unload_commands(orphan, Target::SystemdUser).expect("systemd"),
        [
            "systemctl --user stop nika.arm.0a1b2c3d.gone.timer nika.arm.0a1b2c3d.gone.service",
            "systemctl --user daemon-reload",
        ]
    );
    remove_orphan(orphan, &project).expect("removed");
    assert!(!dir.join("nika.arm.0a1b2c3d.gone.timer").exists());
    assert!(!dir.join("nika.arm.0a1b2c3d.gone.service").exists());
    assert!(
        dir.join("nika.arm.0a1b2c3d.daily.timer").exists(),
        "still armed"
    );
    assert!(
        dir.join("nika.arm.9f8e7d6c.gone.timer").exists(),
        "never touched"
    );
    assert!(
        dir.join("nika.serve.0a1b2c3d.service").exists(),
        "the serve unit stays"
    );
}

/// An orphan under this project's key whose header does not name this
/// project (stripped by hand, or another project's file) is never removed.
#[test]
fn an_orphan_without_this_projects_header_is_never_removed() {
    let scratch = tempfile::tempdir().expect("scratch dir");
    let dir = scratch.path();
    let project = ProjectUnits::new(KEY.to_owned(), dir.join("p/nika.yaml"));
    let path = dir.join("nika.arm.0a1b2c3d.gone.plist");
    std::fs::write(&path, "<plist/>").expect("unmarked unit");

    let orphans = orphan_units(dir, &[], Target::Launchd, &project);

    assert_eq!(orphans[0].owner, UnitOwner::Unmarked);
    assert_eq!(
        orphan_unload_commands(&orphans[0], Target::Launchd).expect("launchd"),
        ["launchctl bootout gui/$UID/nika.arm.0a1b2c3d.gone"]
    );
    assert!(remove_orphan(&orphans[0], &project).is_err());
    assert!(path.exists(), "never removed");
}
